    ($SATQ$d0e614a6$SATQ$, $SATQ$3e65e30b-6f1f-4e34-9ac7-2f2019988ed3$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 2, $SATQ$Math$SATQ$, $SATQ$Algebra$SATQ$, $SATQ$H$SATQ$, $SATQ$H.C.$SATQ$, $SATQ$Linear equations in two variables$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, NULL, $SATQ$<p style="text-align: center;"><math alttext="three fifths x plus three fourths y equals 7"><mfrac><mn>3</mn><mn>5</mn></mfrac><mi>x</mi><mo>+</mo><mfrac><mn>3</mn><mn>4</mn></mfrac><mi>y</mi><mo>=</mo><mn>7</mn></math></p>
